-- MAJ63 C : après 63b. Réexécutable.
begin;
alter table public.workshop_polls add column if not exists results_published boolean not null default false;
alter table public.workshop_polls add column if not exists closing_note text not null default '';
create or replace function public.workshop_poll_publish(p_id uuid,p_publish boolean,p_note text) returns void language plpgsql security definer set search_path='' as $$declare a jsonb;begin a:=workshop_private.actor();perform workshop_private.assert_section('polls');if not (a->>'manager')::boolean then raise exception 'Réservé aux gestionnaires.' using errcode='42501';end if;if p_publish is null or p_note is null or length(p_note)>4000 then raise exception 'Bilan invalide.';end if;update public.workshop_polls set results_published=p_publish,closing_note=trim(p_note) where id=p_id and closed;if not found then raise exception 'Clôture le sondage avant de publier son bilan.';end if;end $$;
do $$begin if to_regprocedure('public.workshop_poll_get_before63(uuid)') is null then alter function public.workshop_poll_get(uuid) rename to workshop_poll_get_before63;end if;end $$;
create or replace function public.workshop_poll_get(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;p public.workshop_polls%rowtype;begin r:=public.workshop_poll_get_before63(p_id);select * into p from public.workshop_polls where id=p_id;r:=r||jsonb_build_object('results_published',p.results_published,'closing_note',case when p.closed and ((r->>'can_manage')::boolean or p.results_published) then p.closing_note else '' end);if p.closed and not p.results_published and not (r->>'can_manage')::boolean then r:=r||jsonb_build_object('results','[]'::jsonb);end if;return r;end $$;
alter table public.workshop_custom_buttons add column if not exists required boolean not null default false;
alter table public.workshop_custom_buttons add column if not exists required_reason text not null default '';
alter table public.workshop_custom_buttons add column if not exists required_poll uuid references public.workshop_polls(id) on delete set null;
alter table public.workshop_custom_buttons add column if not exists requirement_version integer not null default 1;
create table if not exists workshop_private.button_ack(user_id uuid references auth.users(id) on delete cascade,button_id uuid references public.workshop_custom_buttons(id) on delete cascade,version integer not null,created_at timestamptz not null default now(),primary key(user_id,button_id));
create or replace function public.workshop_save_button_v63(p_id uuid,p_label text,p_url text,p_audience text,p_enabled boolean,p_position integer,p_color text,p_required boolean,p_reason text,p_poll uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;b public.workshop_custom_buttons%rowtype;begin
if p_required is null or p_reason is null or length(p_reason)>500 or (p_required and trim(p_reason)='') then raise exception 'Précise pourquoi ce bouton est obligatoire (500 caractères maximum).';end if;
if p_required and p_poll is not null and not exists(select 1 from public.workshop_polls where id=p_poll and not closed) then raise exception 'Choisis un sondage ouvert.';end if;
if p_poll is not null and position('poll='||p_poll::text in p_url)=0 then raise exception 'Lien du sondage incohérent.';end if;
if p_required and p_poll is null and p_url ~ '[?&]poll=' then raise exception 'Sélectionne le sondage dans la liste.';end if;
r:=public.workshop_save_button(p_id,p_label,p_url,p_audience,p_enabled,p_position,p_color);select * into b from public.workshop_custom_buttons where id=(r->>'id')::uuid for update;
update public.workshop_custom_buttons set required=p_required,required_reason=trim(p_reason),required_poll=p_poll,requirement_version=requirement_version+1 where id=b.id;return r;end $$;
create or replace function public.workshop_required_buttons() returns jsonb language plpgsql security definer set search_path='' as $$declare a jsonb;begin a:=workshop_private.actor_before30();if (a->>'manager')::boolean or a->>'role'='guest' then return '[]';end if;
return(select coalesce(jsonb_agg(to_jsonb(b) order by b.position,b.label),'[]') from public.workshop_custom_buttons b where b.enabled and b.required and (b.audience='all' or (b.audience='encadrants' and exists(select 1 from public.workshop_staff where id=a->>'self' and lower(trim(team))='encadrants'))) and case when b.required_poll is not null then exists(select 1 from public.workshop_polls p where p.id=b.required_poll and not p.closed) and not exists(select 1 from public.workshop_votes v where v.poll_id=b.required_poll and v.user_id=auth.uid()) and not exists(select 1 from public.workshop_sections where section='polls' and disabled) else b.url !~ '[?&]poll=' and not exists(select 1 from workshop_private.button_ack x where x.button_id=b.id and x.user_id=auth.uid() and x.version=b.requirement_version) end);end $$;
create or replace function public.workshop_required_ack(p_id uuid,p_version integer) returns void language plpgsql security definer set search_path='' as $$begin
if not exists(select 1 from jsonb_array_elements(public.workshop_required_buttons())x where x->>'id'=p_id::text and (x->>'requirement_version')::integer=p_version and x->>'required_poll' is null) then raise exception 'Action modifiée ou réponse au sondage requise.';end if;
insert into workshop_private.button_ack(user_id,button_id,version) values(auth.uid(),p_id,p_version) on conflict(user_id,button_id) do update set version=excluded.version,created_at=now();end $$;
revoke all on function public.workshop_poll_get_before63(uuid),public.workshop_poll_get(uuid),public.workshop_poll_publish(uuid,boolean,text),public.workshop_save_button_v63(uuid,text,text,text,boolean,integer,text,boolean,text,uuid),public.workshop_required_buttons(),public.workshop_required_ack(uuid,integer) from public,anon,authenticated;
grant execute on function public.workshop_poll_get(uuid),public.workshop_poll_publish(uuid,boolean,text),public.workshop_save_button_v63(uuid,text,text,text,boolean,integer,text,boolean,text,uuid),public.workshop_required_buttons(),public.workshop_required_ack(uuid,integer) to authenticated;
notify pgrst,'reload schema';commit;
